import torch
import torch.nn as nn
import torch.nn.functional as F
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l3_p25_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor shufflenet_dw_bn_shuffle_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps,
    int64_t groups
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("shufflenet_dw_bn_shuffle_cuda", &shufflenet_dw_bn_shuffle_cuda,
          "ShuffleNet depthwise+bn+shuffle (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Each thread handles one (n, out_c, h, w) output element.
// The channel shuffle permutation for groups G and C channels:
//   src_c = (out_c % (C/G)) * G + (out_c / (C/G))
// After computing depthwise conv on src_c, apply BN2 affine from running stats
// using src_c (BN was computed before shuffle), then write to shuffled position.
__global__ void dw_bn_shuffle_kernel(
    const float* __restrict__ x,       // [N, C, H, W]
    const float* __restrict__ weight,  // [C, 1, 3, 3] depthwise
    const float* __restrict__ bn_w,    // [C]
    const float* __restrict__ bn_b,    // [C]
    const float* __restrict__ run_mean,// [C]
    const float* __restrict__ run_var, // [C]
    float*       __restrict__ out,     // [N, C, H, W] shuffled
    int N, int C, int H, int W,
    float eps,
    int groups
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H * W;
    if (idx >= total) return;

    int w_idx = idx % W;
    int h_idx = (idx / W) % H;
    int c_out = (idx / (W * H)) % C;   // shuffled output channel
    int n     = idx / (W * H * C);

    // inverse shuffle: find source channel
    int channels_per_group = C / groups;
    int src_c = (c_out % channels_per_group) * groups + (c_out / channels_per_group);

    // depthwise 3x3 conv with padding=1 on src_c
    float val = 0.0f;
    for (int kh = 0; kh < 3; kh++) {
        int ih = h_idx + kh - 1;
        if (ih < 0 || ih >= H) continue;
        for (int kw = 0; kw < 3; kw++) {
            int iw = w_idx + kw - 1;
            if (iw < 0 || iw >= W) continue;
            int x_idx = n * C * H * W + src_c * H * W + ih * W + iw;
            int w_idx2 = src_c * 9 + kh * 3 + kw;
            val += x[x_idx] * weight[w_idx2];
        }
    }

    // BN2 inference: normalize over src_c stats, apply affine
    float inv_std = rsqrtf(run_var[src_c] + eps);
    val = (val - run_mean[src_c]) * inv_std * bn_w[src_c] + bn_b[src_c];

    // write directly to shuffled output position
    out[idx] = val;
}

torch::Tensor shufflenet_dw_bn_shuffle_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps,
    int64_t groups
) {
    TORCH_CHECK(x.is_cuda() && x.is_contiguous(), "x must be contiguous CUDA tensor");
    TORCH_CHECK(weight.is_cuda() && weight.is_contiguous(), "weight must be contiguous CUDA tensor");
    int N = x.size(0), C = x.size(1), H = x.size(2), W = x.size(3);
    TORCH_CHECK(C % groups == 0, "C must be divisible by groups");

    auto out = torch::empty_like(x);
    int total = N * C * H * W;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    dw_bn_shuffle_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bn_weight.data_ptr<float>(),
        bn_bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W,
        (float)eps,
        (int)groups
    );
    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, groups=3):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        assert out_channels % 4 == 0
        mid_channels = out_channels // 4
        self.groups = groups
        self.conv1 = nn.Conv2d(in_channels, mid_channels, kernel_size=1, stride=1, padding=0, groups=groups, bias=False)
        self.bn1 = nn.BatchNorm2d(mid_channels)
        self.conv2 = nn.Conv2d(mid_channels, mid_channels, kernel_size=3, stride=1, padding=1, groups=mid_channels, bias=False)
        self.bn2 = nn.BatchNorm2d(mid_channels)
        self.conv3 = nn.Conv2d(mid_channels, out_channels, kernel_size=1, stride=1, padding=0, groups=groups, bias=False)
        self.bn3 = nn.BatchNorm2d(out_channels)
        if in_channels == out_channels:
            self.shortcut = nn.Sequential()
        else:
            self.shortcut = nn.Sequential(
                nn.Conv2d(in_channels, out_channels, kernel_size=1, stride=1, padding=0, bias=False),
                nn.BatchNorm2d(out_channels)
            )
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Forward pass for ShuffleNet unit.

                :param x: Input tensor, shape (batch_size, in_channels, height, width)
                :return: Output tensor, shape (batch_size, out_channels, height, width)
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if not self.training:
            scale1 = self.bn1.weight / torch.sqrt(self.bn1.running_var + self.bn1.eps)
            bias1 = self.bn1.bias - self.bn1.running_mean * scale1
            weight1 = self.conv1.weight * scale1.reshape(-1, 1, 1, 1)
            out = F.relu(F.conv2d(x, weight1, bias1, stride=self.conv1.stride, padding=self.conv1.padding, dilation=self.conv1.dilation, groups=self.conv1.groups))
        else:
            out = F.relu(self.bn1(self.conv1(x)))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        if (not self.training
                        and out.is_cuda
                        and out.is_contiguous()
                        and self.conv2.weight.is_contiguous()
                        and out.dtype == torch.float32):
                    # fused depthwise conv + bn2 affine + channel shuffle in one kernel
                    out = _stark_get_extension().shufflenet_dw_bn_shuffle_cuda(
                        out,
                        self.conv2.weight,
                        self.bn2.weight,
                        self.bn2.bias,
                        self.bn2.running_mean,
                        self.bn2.running_var,
                        self.bn2.eps,
                        self.groups,
                    )
                    # mark that shuffle is already done so forward_stmt_4 can skip it
                    self._shuffle_done = True
                else:
                    out = self.bn2(self.conv2(out))
                    self._shuffle_done = False
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        out = F.channel_shuffle(out, self.groups)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        if not self.training:
            scale3 = self.bn3.weight / torch.sqrt(self.bn3.running_var + self.bn3.eps)
            bias3 = self.bn3.bias - self.bn3.running_mean * scale3
            weight3 = self.conv3.weight * scale3.reshape(-1, 1, 1, 1)
            out = F.relu(F.conv2d(out, weight3, bias3, stride=self.conv3.stride, padding=self.conv3.padding, dilation=self.conv3.dilation, groups=self.conv3.groups))
        else:
            out = F.relu(self.bn3(self.conv3(out)))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        if len(self.shortcut) == 0:
            shortcut = x
        elif not self.training and len(self.shortcut) == 2:
            sc_conv = self.shortcut[0]
            sc_bn = self.shortcut[1]
            sc_scale = sc_bn.weight / torch.sqrt(sc_bn.running_var + sc_bn.eps)
            sc_bias = sc_bn.bias - sc_bn.running_mean * sc_scale
            sc_weight = sc_conv.weight * sc_scale.reshape(-1, 1, 1, 1)
            shortcut = F.conv2d(x, sc_weight, sc_bias, stride=sc_conv.stride, padding=sc_conv.padding, dilation=sc_conv.dilation, groups=sc_conv.groups)
        else:
            shortcut = self.shortcut(x)
        out = out + shortcut
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_7>>>
        return out
        # <<<END_IMPROVE>>>

