# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Each thread handles one (n, out_c, h, w) output element.
// The channel shuffle permutation for groups G and C channels:
//   src_c = (out_c % (C/G)) * G + (out_c / (C/G))
// After computing depthwise conv on src_c, apply BN2 affine from running stats
// using src_c (BN was computed before shuffle), then write to shuffled position.
__global__ void dw_bn_shuffle_kernel(
    const float* __restrict__ x,       // [N, C, H, W]
    const float* __restrict__ weight,  // [C, 1, 3, 3] depthwise
    const float* __restrict__ bn_w,    // [C]
    const float* __restrict__ bn_b,    // [C]
    const float* __restrict__ run_mean,// [C]
    const float* __restrict__ run_var, // [C]
    float*       __restrict__ out,     // [N, C, H, W] shuffled
    int N, int C, int H, int W,
    float eps,
    int groups
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H * W;
    if (idx >= total) return;

    int w_idx = idx % W;
    int h_idx = (idx / W) % H;
    int c_out = (idx / (W * H)) % C;   // shuffled output channel
    int n     = idx / (W * H * C);

    // inverse shuffle: find source channel
    int channels_per_group = C / groups;
    int src_c = (c_out % channels_per_group) * groups + (c_out / channels_per_group);

    // depthwise 3x3 conv with padding=1 on src_c
    float val = 0.0f;
    for (int kh = 0; kh < 3; kh++) {
        int ih = h_idx + kh - 1;
        if (ih < 0 || ih >= H) continue;
        for (int kw = 0; kw < 3; kw++) {
            int iw = w_idx + kw - 1;
            if (iw < 0 || iw >= W) continue;
            int x_idx = n * C * H * W + src_c * H * W + ih * W + iw;
            int w_idx2 = src_c * 9 + kh * 3 + kw;
            val += x[x_idx] * weight[w_idx2];
        }
    }

    // BN2 inference: normalize over src_c stats, apply affine
    float inv_std = rsqrtf(run_var[src_c] + eps);
    val = (val - run_mean[src_c]) * inv_std * bn_w[src_c] + bn_b[src_c];

    // write directly to shuffled output position
    out[idx] = val;
}

torch::Tensor shufflenet_dw_bn_shuffle_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
